// ═══ RACE CONDITION: without synchronization ═══
class UnsafeAccount {
    int balance = 100000;

    void debit(int amount) {
        // Thread-1: reads balance=100000
        // Thread-2: reads balance=100000 (stale!)
        int newBalance = balance - amount;
        // Thread-1: writes 50000
        // Thread-2: writes 50000 (overwrites Thread-1's write!)
        balance = newBalance;
        // Expected: 0. Actual: 50000. LOST UPDATE!
    }
}

// ═══ FIX: synchronized — mutual exclusion ═══
class SafeAccount {
    int balance = 100000;

    synchronized void debit(int amount) {
        // Only ONE thread can execute this at a time!
        // Thread-1: acquires lock → reads 100000 → writes 50000 → releases lock
        // Thread-2: acquires lock → reads 50000 → writes 0 → releases lock
        // Correct: 0!
        balance -= amount;
    }

    synchronized int getBalance() {
        return balance;
    }
}

// ═══ INTRINSIC MONITOR — what every object has ═══
// Every Java object header contains:
// 1. Mark Word: hash code, GC age, lock state, thread ID (when locked)
// 2. Class Pointer: points to class metadata
//
// Lock states in Mark Word:
// - Unlocked: no thread holds the lock
// - Biased: one thread holds the lock (optimized for single-thread access)
// - Thin/Lightweight: CAS-based lock (low contention)
// - Fat/Heavyweight: OS mutex (high contention — threads parked by OS)
//
// JVM OPTIMIZES locking:
// Biased locking: if only ONE thread ever locks this object → zero overhead!
// Lightweight lock: if 2 threads alternate → CAS-based, no OS call
// Heavyweight lock: if contention → OS mutex, thread parking (expensive)

// ═══ SYNCHRONIZATION GUARANTEES ═══
// 1. MUTUAL EXCLUSION: only one thread in the critical section
// 2. VISIBILITY (happens-before): changes made in synchronized block
//    are visible to the NEXT thread that acquires the SAME lock
// 3. ATOMICITY: the critical section executes as one indivisible unit
//    (from other threads' perspective)

// ═══ MONITOR OPERATIONS ═══
// synchronized(obj) { }  → acquire obj's monitor lock
// obj.wait()             → release lock + enter wait set (WAITING state)
// obj.notify()           → move ONE thread from wait set to entry set
// obj.notifyAll()        → move ALL threads from wait set to entry set
// RULE: wait/notify MUST be called while holding the lock (inside synchronized)!
