// ─── File: src/test/java/com/bank/sync/SynchronizationTest.java ───
package com.bank.sync;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class SynchronizationTest {

    // ═══ UNSAFE: race condition ═══
    static class UnsafeAccount {
        int balance;
        UnsafeAccount(int balance) { this.balance = balance; }
        void debit(int amount) {
            if (balance >= amount) {
                // Thread might be preempted HERE — another thread reads stale balance!
                balance -= amount;
            }
        }
    }

    // ═══ SAFE: synchronized ═══
    static class SafeAccount {
        int balance;
        SafeAccount(int balance) { this.balance = balance; }
        synchronized void debit(int amount) {
            if (balance >= amount) {
                balance -= amount;  // only ONE thread at a time!
            }
        }
        synchronized int getBalance() { return balance; }
    }

    @Test
    void unsafeAccount_raceCondition() throws InterruptedException {
        // Run multiple times — race condition is probabilistic
        int failures = 0;
        for (int trial = 0; trial < 100; trial++) {
            UnsafeAccount account = new UnsafeAccount(100);
            CountDownLatch latch = new CountDownLatch(100);

            for (int i = 0; i < 100; i++) {
                new Thread(() -> {
                    account.debit(1);
                    latch.countDown();
                }).start();
            }
            latch.await();
            if (account.balance != 0) failures++;
        }
        // At least SOME trials should show corruption (balance != 0)
        System.out.println("Race condition failures: " + failures + "/100 trials");
    }

    @Test
    void safeAccount_noRaceCondition() throws InterruptedException {
        SafeAccount account = new SafeAccount(100000);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                account.debit(1000);
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(account.getBalance()).isEqualTo(0);  // ALWAYS correct!
    }

    @Test
    void overdraftProtection_synchronized() throws InterruptedException {
        SafeAccount rajesh = new SafeAccount(100000);
        CountDownLatch latch = new CountDownLatch(2);

        // Two transfers attempt to debit more than half the balance simultaneously
        Thread t1 = new Thread(() -> { rajesh.debit(60000); latch.countDown(); });
        Thread t2 = new Thread(() -> { rajesh.debit(50000); latch.countDown(); });

        t1.start(); t2.start();
        latch.await();

        // Only ONE should succeed (60000 or 50000), not both!
        assertThat(rajesh.getBalance()).isIn(40000, 50000);
        // If both succeeded: balance would be -10000 (WRONG!)
    }

    @Test
    void monitor_onlyOneThreadAtATime() throws InterruptedException {
        Object lock = new Object();
        int[] counter = {0};
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                synchronized (lock) {
                    int temp = counter[0];
                    temp++;  // read-modify-write is ATOMIC inside synchronized!
                    counter[0] = temp;
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter[0]).isEqualTo(50);  // exactly 50!
    }
}
